package com.autoops.execution.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="approval_requests")public class ApprovalRequest{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="step_run_id",nullable=false)private Long stepRunId;@Column(nullable=false)private String status="PENDING";@Column(name="requested_at",nullable=false)private Instant requestedAt=Instant.now();@Column(name="approved_by")private Long approvedBy;@Column(name="decided_at")private Instant decidedAt;public Long getId(){return id;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public void setStepRunId(Long v){stepRunId=v;}public void setApprovedBy(Long v){approvedBy=v;}public void setDecidedAt(Instant v){decidedAt=v;}}
